PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?result WHERE {
  BIND(<http://ld.company.org/prod-instances/empl-Karen.Brant%40company.org> AS ?employee)
  {
    ?employee ?p ?result .
  }
  UNION
  {
    ?result ?p ?employee .
  }
  ?result a pv:Department .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

ASK {
  <http://ld.company.org/prod-instances/empl-Sabrina.Geiger%40company.org> pv:email ?email .
  prodi:dept-85880 a pv:Department .
  { <http://ld.company.org/prod-instances/empl-Sabrina.Geiger%40company.org> ?rel prodi:dept-85880 . }
  UNION
  { prodi:dept-85880 ?rel <http://ld.company.org/prod-instances/empl-Sabrina.Geiger%40company.org> . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result a pv:Agent ;
          pv:hasExpertise ?item .
  OPTIONAL { ?item rdfs:label ?label. }
  FILTER (
    regex(str(?item), "Transistor", "i")
    || (bound(?label) && regex(str(?label), "Transistor", "i"))
  )
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result a foaf:Person ;
          pv:hasRole pv:SensorSpecialist .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?result WHERE {
  {
    ?person pv:manages prodi:dept-41622 .
  }
  UNION
  {
    ?person pv:hasDirectReport ?member .
    ?member pv:memberOf prodi:dept-41622 .
  }
  OPTIONAL { ?person foaf:name ?name }
  OPTIONAL { ?person rdfs:label ?label }
  BIND(COALESCE(?name, ?label, STR(?person)) AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?dept a pv:Department ;
        rdfs:label ?dlabel .
  FILTER(regex(str(?dlabel), "Datenmanagement", "i"))
  {
    ?result a pv:Employee ;
            pv:responsibleFor ?dept .
  }
  UNION
  {
    ?dept pv:hasManager ?result .
    ?result a pv:Employee .
  }
  UNION
  {
    ?result a pv:Employee ;
            pv:memberOf ?dept ;
            pv:hasDirectReport ?any .
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?result WHERE {
  {
    prodi:hw-M558-2275045 ?p ?result .
    ?result a pv:Department .
  }
  UNION
  {
    ?result ?p prodi:hw-M558-2275045 .
    ?result a pv:Department .
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?result WHERE {
  ?result a pv:Department ;
          pv:responsibleFor prodi:hw-M558-2275045 .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?prod) AS ?count) WHERE {
  {
    ?prod rdfs:label ?label .
    FILTER(regex(str(?label), "Sensor Switch", "i"))
  }
  UNION
  {
    ?prod pv:memberOf ?cat .
    ?cat rdfs:label ?catLabel .
    FILTER(regex(str(?catLabel), "Sensor Switch", "i"))
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  {
    SELECT (COUNT(DISTINCT ?p) AS ?count) WHERE {
      ?p pv:hasCategory ?cat .
      ?cat rdfs:label ?label .
      FILTER(
        CONTAINS(LCASE(STR(?label)), "sensor") &&
        CONTAINS(LCASE(STR(?label)), "schalter")
      )
    }
  }
  BIND(?count AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?result WHERE {
  VALUES ?transducer { prodi:prod-cat-Transducer prodi:hw-W304-6414305 }

  {
    # Departments that directly list transducer as an area of expertise
    ?result a pv:Department .
    ?result pv:areaOfExpertise ?transducer .
  }
  UNION
  {
    # Departments that are related to a person who has transducer as an area of expertise
    ?result a pv:Department .
    ?person a pv:Person .
    ?person pv:areaOfExpertise ?transducer .
    ?person pv:worksIn ?result .
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  # find people with expertise in sensors/wandler (transducers)
  ?person pv:areaOfExpertise ?exp .
  FILTER(regex(str(?exp), "sensor|wandler", "i"))

  # consider several ways a person can be linked to a department
  {
    ?dept pv:hasManager ?person .
  } UNION {
    ?dept pv:hasDirectReport ?person .
  } UNION {
    ?dept pv:responsibleFor ?person .
  } UNION {
    ?person pv:worksFor ?dept .
  }

  # ensure we only return department entities
  ?dept a pv:Department .

  OPTIONAL { ?dept rdfs:label ?label . }
  BIND(COALESCE(?label, STR(?dept)) AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result a pv:Agent ;
          pv:offers ?prod .
  OPTIONAL { ?result pv:addressText ?addr . }
  ?prod a pv:Product ;
        rdfs:label ?label .

  OPTIONAL {
    ?result pv:country ?country .
    ?country rdfs:label ?countryLabel .
  }

  FILTER(
    ( CONTAINS(LCASE(?label), "kompensat") || CONTAINS(LCASE(?label), "compensat") )
  )

  FILTER(
    ( bound(?addr) && ( CONTAINS(LCASE(?addr), "frankreich") || CONTAINS(LCASE(?addr), "france") ) )
    ||
    ( bound(?countryLabel) && ( CONTAINS(LCASE(?countryLabel), "frankreich") || CONTAINS(LCASE(?countryLabel), "france") || CONTAINS(LCASE(?countryLabel), "français") ) )
  )
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
