ASK WHERE {
  {
    ?s a pv:Supplier ;
       pv:addressLocality dbpedia:Toulouse .
  }
  UNION
  {
    ?s a pv:Supplier ;
       pv:addressLocality ?loc .
    FILTER(isLiteral(?loc) && regex(str(?loc), "Toulouse", "i"))
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result a pv:Service ;
          pv:price ?price .

  {
    SELECT (MAX(?p) AS ?maxPrice) WHERE {
      ?s a pv:Service ;
         pv:price ?p .
    }
  }

  FILTER(?price = ?maxPrice)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?result pv:responsibleFor ?service .
  ?service a pv:Service .

  # Service price may be represented directly as a literal...
  OPTIONAL { ?service pv:price ?priceLit . FILTER(isLiteral(?priceLit)) }

  # ...or as a Price node with an amount property
  OPTIONAL {
    ?service pv:price ?priceNode .
    ?priceNode a pv:Price ;
               pv:amount ?priceAmount .
  }

  BIND(COALESCE(?priceAmount, ?priceLit) AS ?price)
  FILTER(bound(?price))
}
ORDER BY DESC(xsd:decimal(?price))
LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result rdf:type pv:Coil ;
          pv:height_mm ?width ;
          pv:height_mm ?depth ;
          pv:weight_g ?weight .
  FILTER(?width <= 15 && ?depth <= 15)
  FILTER NOT EXISTS {
    ?other rdf:type pv:Coil ;
           pv:height_mm ?ow ;
           pv:height_mm ?od ;
           pv:weight_g ?owt .
    FILTER(?ow <= 15 && ?od <= 15 && ?owt > ?weight)
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?result WHERE {
  { <http://ld.company.org/prod-instances/hw-U990-5234138> pv:compatibleProduct ?result . }
  UNION
  { ?result pv:compatibleProduct <http://ld.company.org/prod-instances/hw-U990-5234138> . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?result WHERE {
  {
    prodi:hw-U990-5234138 pv:compatibleProduct ?result .
  }
  UNION
  {
    ?result pv:compatibleProduct prodi:hw-U990-5234138 .
  }

  ?result pv:hasSupplier ?sup .

  OPTIONAL { ?sup rdfs:label ?supLabel . }
  OPTIONAL { ?sup pv:country ?country . }

  FILTER (
    (bound(?supLabel) && regex(str(?supLabel), "United[_ ]?States|\\bUS\\b|\\bUSA\\b", "i"))
    ||
    (bound(?country) && regex(str(?country), "United[_ ]?States|\\bUS\\b|\\bUSA\\b", "i"))
    ||
    (bound(?country) && ?country = dbpedia:United_States)
  )
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX dbpedia: <http://dbpedia.org/resource/>

SELECT DISTINCT ?result WHERE {
  # find the U990-LCD inductor by label (flexible matching)
  ?inductor rdfs:label ?indLabel .
  FILTER regex(?indLabel, "U990\\s*-?LCD", "i") .

  # products compatible with that inductor (either direction)
  { ?result pv:compatibleProduct ?inductor . }
  UNION
  { ?inductor pv:compatibleProduct ?result . }

  # the product must have a supplier whose label or country indicates United States
  ?result pv:hasSupplier ?supplier .
  OPTIONAL { ?supplier rdfs:label ?supplierLabel . }
  OPTIONAL { ?supplier foaf:based_near ?basedNear . }
  OPTIONAL { ?supplier rdfs:comment ?supplierComment . }
  OPTIONAL { ?supplier pv:country ?supplierCountry . }
  OPTIONAL { ?supplier pv:basedIn ?supplierBasedIn . }

  FILTER(
    (bound(?supplierCountry) && ( ?supplierCountry = dbpedia:United_States || regex(str(?supplierCountry), "United States|USA|US|Vereinigte Staaten", "i") ))
    ||
    (bound(?supplierBasedIn) && ( ?supplierBasedIn = dbpedia:United_States || regex(str(?supplierBasedIn), "United States|USA|US|Vereinigte Staaten", "i") ))
    ||
    (bound(?supplierLabel) && regex(str(?supplierLabel), "\\b(United States|USA|US|Vereinigte Staaten)\\b", "i"))
    ||
    (bound(?supplierComment) && regex(str(?supplierComment), "United States|USA|Vereinigte Staaten", "i"))
    ||
    (bound(?basedNear) && regex(str(?basedNear), "United States|USA|Vereinigte Staaten", "i"))
  )
}

