PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?result WHERE {
  ?result pv:reliabilityIndex ?d ;
          rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "coil"))
  {
    SELECT (MAX(?d2) AS ?maxD) WHERE {
      ?c pv:reliabilityIndex ?d2 ;
         rdfs:label ?lbl .
      FILTER(CONTAINS(LCASE(STR(?lbl)), "coil"))
    }
  }
  FILTER(?d = ?maxD)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
