SELECT DISTINCT ?result WHERE {
  ?result a pv:Hardware ;
          rdfs:label ?label ;
          pv:weight_g ?densityVal .
  FILTER(regex(str(?label), "Spule|Inductor", "i"))
}
ORDER BY DESC(xsd:decimal(?densityVal))
